insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-52-L2', '5.2 Agriculture and food · Lesson 2 (HL): Alternative farming, regenerative agriculture, diets and the global food system', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 3, "pts": [["regenerative+soil", "regenerative+biodiversity", "regenerative+low input"], ["greenhouse+yield", "greenhouse+productivity", "greenhouse+per hectare"], ["energy", "capital", "cost", "input"]], "tips": ["Soil, yield, inputs."]}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["distribution", "unequal", "access"], ["poverty", "afford", "waste", "conflict", "trade"]], "tips": ["Access, not supply."]}]}, "models": {"1": [["Q1", "Regenerative farming rebuilds soil and biodiversity with low external inputs [1]; greenhouse farming achieves very high yields per hectare [1]; but greenhouse systems need high energy and capital inputs, while regenerative yields may be lower [1]."]], "2": [["Q2", "Food is unequally distributed between and within countries [1]; poverty, conflict, trade patterns and waste mean many people cannot access or afford enough food [1]."]], "6": [["Exit ticket", "Mixed cropping, perennial plants, agroforestry, composting or integrating livestock."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q2", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
