insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-61-L2', '6.1 Introduction to the atmosphere · Lesson 2 (HL): The dynamic atmosphere, Milankovitch cycles and the evolution of Earth''s atmosphere', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["gravity"], ["fewer", "less air above", "density", "molecules"]], "tips": ["Gravity and air above."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 3, "n": 3, "ans": ["Eccentricity", "Obliquity", "Precession"], "tip": "Shape, tilt, wobble."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["photosynthe", "cyanobacteria"], ["oxygen", "ozone", "co2", "carbon dioxide"]], "tips": ["Which organisms, which gas?"]}]}, "models": {"1": [["Q1", "Gravity pulls air molecules towards Earth''s surface [1], so there are fewer molecules (lower density) and less weight of air above at higher altitudes [1]."]], "2": [["Q2", "Eccentricity; obliquity; precession."], ["Q3", "Photosynthetic cyanobacteria released oxygen [1], raising atmospheric O₂, allowing an ozone layer to form and reducing CO₂ [1]."]], "6": [["Exit ticket", "Milankovitch (orbital) cycles changing the solar radiation reaching Earth."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '37f21d67-ae9e-5be6-9566-499ba929c91a', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = '6.2' limit 1), '6.2 Climate change—causes and impacts · Lesson 2 (HL): Climate data and models, tipping cascades, responsibility and vulnerability', 'IB DP ESS · 6.2 Climate change—causes and impacts', '/ess62-lesson2/', 'ESS-62-L2', 7, 182 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-62-L2', '6.2 Climate change—causes and impacts · Lesson 2 (HL): Climate data and models, tipping cascades, responsibility and vulnerability', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["uncertain", "unknown", "future emissions", "depends"], ["range", "compare", "policy", "different outcomes"]], "tips": ["Future human choices."]}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["trigger", "one tipping point", "interact", "another"], ["greenland", "amoc", "atlantic", "amazon", "permafrost", "ice"]], "tips": ["Domino effect."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 3, "pts": [["emission", "contributed least", "historical"], ["vulnerable", "agriculture", "drought", "coast", "exposure"], ["adapt", "money", "resources", "infrastructure", "capacity"]], "tips": ["Responsibility, exposure, capacity."]}]}, "models": {"1": [["Q1", "Future emissions depend on uncertain human choices such as policy and technology [1], so models run several scenarios to show the range of possible outcomes and help policymakers compare options [1]."]], "2": [["Q2", "A tipping cascade is when crossing one tipping point triggers others, like dominoes [1]; e.g. Greenland ice melt slows the Atlantic overturning circulation, which changes rainfall and causes Amazon dieback [1]."]], "3": [["Q3", "Low-income countries have contributed least to historical emissions [1]; many are more exposed, depending on rain-fed agriculture or low-lying coasts [1]; they have less money and infrastructure to adapt [1]."]], "6": [["Exit ticket", "A possible future path of emissions and socio-economic development used as input to a climate model."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q2", "q3_0": "Q3", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '16d46a63-0f4f-5b24-af74-ca58ffd45159', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = '6.3' limit 1), '6.3 Climate change—mitigation and adaptation · Lesson 2 (HL): Global governance, IPCC scenarios, technology, geoengineering and perspectives', 'IB DP ESS · 6.3 Climate change—mitigation and adaptation', '/ess63-lesson2/', 'ESS-63-L2', 8, 192 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-63-L2', '6.3 Climate change—mitigation and adaptation · Lesson 2 (HL): Global governance, IPCC scenarios, technology, geoengineering and perspectives', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 3, "pts": [["kyoto+developed", "kyoto+binding"], ["paris+all", "paris+every country", "paris+ndc"], ["paris+not binding", "paris+voluntary", "paris+1.5", "both"]], "tips": ["Who, how binding, aims."]}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["reflect", "cool", "quick", "fast"], ["side effect", "rainfall", "ozone", "acid", "termination", "uneven"], ["not reduce co2", "acidification", "moral hazard", "governance", "conclusion"]], "tips": ["Benefit, risk, judgement."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["shared", "common", "atmosphere"], ["benefit", "costs shared", "free rider", "each country", "overuse"]], "tips": ["Shared atmosphere."]}]}, "models": {"1": [["Q1", "Kyoto set legally binding targets for developed countries only [1]; Paris requires all countries to set their own nationally determined contributions [1]; Paris targets are voluntary and not legally binding, aiming to limit warming to well below 2 °C and pursue 1.5 °C [1]."]], "2": [["Q2", "Injecting aerosols could reflect sunlight and cool the planet quickly [1]; however it may change rainfall patterns unevenly, damage ozone, and cause rapid warming if stopped (termination shock) [1]; it does not reduce CO₂ or ocean acidification and may reduce motivation to cut emissions, so it should not replace mitigation [1]."]], "3": [["Q3", "The atmosphere is a shared resource that no single country owns [1]; each country benefits from emitting while the costs are shared by all, so emissions continue without collective agreement [1]."]], "6": [["Exit ticket", "Intergovernmental Panel on Climate Change."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q2", "q3_0": "Q3", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '5381a844-b711-5357-b5f9-9d5d3dd39f94', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = '6.4' limit 1), '6.4 Stratospheric ozone · Lesson 2 (HL): Halogen chemistry, polar ozone depletion, HFCs and air conditioning', 'IB DP ESS · 6.4 Stratospheric ozone', '/ess64-lesson2/', 'ESS-64-L2', 4, 202 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-64-L2', '6.4 Stratospheric ozone · Lesson 2 (HL): Halogen chemistry, polar ozone depletion, HFCs and air conditioning', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["cold", "polar stratospheric clouds", "winter"], ["sunlight", "spring", "uv", "return"]], "tips": ["Winter clouds, spring sunlight."]}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["greenhouse", "warming", "gwp"], ["kigali", "climate", "potent", "thousands"]], "tips": ["Climate effect."]}]}, "models": {"1": [["Q1", "Very cold winter temperatures form polar stratospheric clouds, on which chlorine is converted to reactive forms [1]; when sunlight returns in spring, it drives rapid destruction of ozone [1]."]], "2": [["Q2", "Many HFCs are very potent greenhouse gases with high global warming potential [1], so the Kigali Amendment phases them down to reduce climate change [1]."]], "6": [["Exit ticket", "It acts as a catalyst and is regenerated."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q2", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '8beec6c6-4d12-5aea-8f3b-50e5c166c5e5', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = '7.1' limit 1), '7.1 Natural resources—uses and management · Lesson 2 (HL): Managing resources: SDGs, EIAs, extraction impacts, short-termism, insecurity and globalization', 'IB DP ESS · 7.1 Natural resources—uses and management', '/ess71-lesson2/', 'ESS-71-L2', 5, 212 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-71-L2', '7.1 Natural resources—uses and management · Lesson 2 (HL): Managing resources: SDGs, EIAs, extraction impacts, short-termism, insecurity and globalization', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 3, "pts": [["baseline", "before"], ["impact", "predict", "identify"], ["mitigat", "alternative", "decision", "public", "reduce"]], "tips": ["Before, predict, reduce."]}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["trade", "import", "supply", "increase"], ["depend", "interdependent", "disrupt", "price", "conflict", "vulnerable"]], "tips": ["Trade benefits and risks."]}]}, "models": {"1": [["Q1", "An EIA is carried out before a development, starting with a baseline study [1]; it predicts the likely environmental and social impacts [1]; it proposes mitigation or alternatives and informs a public decision on whether to approve the project [1]."]], "2": [["Q2", "Global trade allows countries to import resources they lack, increasing supply [1]; but it makes them dependent on others, so conflicts or price shocks can disrupt supplies [1]."]], "6": [["Exit ticket", "A survey of the environment before the development, used for comparison."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q2", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
