insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-72-L2', '7.2 Energy sources—uses and management · Lesson 2 (HL): Energy security, fossil fuel reserves, nuclear power and battery storage', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["import", "supplier", "other countries", "depend"], ["price", "conflict", "cut", "disrupt"]], "tips": ["Supply and price."]}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["low carbon", "low emission", "reliable", "base load"], ["waste", "radioactive", "accident", "expensive", "cost"], ["conclusion", "transition", "depends", "overall"]], "tips": ["Strength, limitation, judgement."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["intermittent", "solar", "wind", "variable"], ["store", "surplus", "backup", "demand", "night"]], "tips": ["Intermittency."]}]}, "models": {"1": [["Q1", "The country relies on other countries for its supply [1], so conflicts, export bans or price rises can cut supply or make energy unaffordable [1]."]], "2": [["Q2", "Nuclear power provides reliable, low-carbon base-load electricity [1]; however it produces long-lived radioactive waste, has accident risks and is very expensive and slow to build [1]; overall it can help the transition away from fossil fuels where countries can manage the waste and costs [1]."]], "3": [["Q3", "Solar and wind are intermittent [1], so batteries store surplus electricity for times of high demand or no sun or wind, replacing fossil-fuel backup [1]."]], "6": [["Exit ticket", "Access to affordable and reliable sources of energy."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q2", "q3_0": "Q3", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'b0020f0c-e261-5c29-aff2-d6eb43f897e2', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = '8.1' limit 1), '8.1 Human populations · Lesson 2 (HL): Population growth and Earth systems, dependency ratios, patterns and environmental migration', 'IB DP ESS · 8.1 Human populations', '/ess81-lesson2/', 'ESS-81-L2', 4, 242 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-81-L2', '8.1 Human populations · Lesson 2 (HL): Population growth and Earth systems, dependency ratios, patterns and environmental migration', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["71.4", "71"], ["youth", "young", "high"]], "tips": ["(18 + 2) ÷ 28 × 100."]}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["yield", "crop", "livelihood", "income", "food"], ["move", "migrat", "city", "urban", "leave"]], "tips": ["Livelihoods."]}]}, "models": {"1": [["Q1", "Dependency ratio = (18 + 2) ÷ 28 × 100 = 71.4 [1]; this is high and mainly due to young dependants, so demand for schools and future jobs will be high [1]."]], "2": [["Q2", "Degraded land produces lower crop yields and less pasture, so people lose their livelihoods and food security [1], forcing them to move, often to cities, in search of work [1]."]], "6": [["Exit ticket", "(Population aged 0–14 + 65+) ÷ population aged 15–64 × 100."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q2", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
