insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-82-L2', '8.2 Urban systems and urban planning · Lesson 2 (HL): Ecological urban planning, sustainable city models and green architecture', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["close", "near", "shorter", "together"], ["walk", "less car", "transport", "emission", "fuel"]], "tips": ["Journeys."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Passive ventilation", "Green roof", "Rainwater harvesting", "Solar panels"], "tip": "One each."}]}, "models": {"1": [["Q1", "Homes, jobs and services are close together [1], so people can walk, cycle or use public transport, reducing car use and emissions [1]."]], "2": [["Q2", "Passive ventilation; green roof; rainwater harvesting; solar panels."]], "6": [["Exit ticket", "Urban compactness, mixed land use, green space, or public transport priority."]]}, "labels": {"q1_0": "Q1", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
