insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-83-L2', '8.3 Urban air pollution · Lesson 2 (HL): Photochemical smog, temperature inversions and tropospheric ozone impacts', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 3, "pts": [["warm air", "warm layer", "above"], ["cool", "cold air", "near the ground", "below"], ["trap", "cannot rise", "not disperse"]], "tips": ["Lid of warm air."]}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["health", "hospital", "medical"], ["work", "productivity", "crop", "economic", "tourism", "school"]], "tips": ["Costs to society."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 3, "pts": [["nox", "nitrogen oxide", "voc", "vehicle"], ["sunlight", "uv", "light"], ["ozone", "secondary", "react"]], "tips": ["Ingredients + sunlight → product."]}]}, "models": {"1": [["Q1", "In an inversion, a layer of warm air lies above [1] cooler, denser air near the ground [1]; the cool air cannot rise, so pollutants are trapped near the surface and cannot disperse [1]."]], "2": [["Q2", "Higher healthcare costs from respiratory illness [1]; lost working days, lower crop yields and reduced economic output [1]."]], "3": [["Q3", "Vehicles emit nitrogen oxides and VOCs [1]; in strong sunlight [1] these react to form tropospheric ozone and other secondary pollutants, producing smog [1]."]], "6": [["Exit ticket", "Surrounding mountains and temperature inversions trap pollutants."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q2", "q3_0": "Q3", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
